def components(grid, color):
    """The 4-connected components of one color as lists of (row, col) cells."""
    h, w = len(grid), len(grid[0]); seen = set(); out = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] == color and (i, j) not in seen:
                st = [(i, j)]; seen.add((i, j)); cells = []
                while st:
                    y, x = st.pop(); cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        a, b = y + dy, x + dx
                        if 0 <= a < h and 0 <= b < w and grid[a][b] == color and (a, b) not in seen:
                            seen.add((a, b)); st.append((a, b))
                out.append(cells)
    return out

def background(grid):
    """The most frequent color in the grid."""
    from collections import Counter
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def solid_output(grid, min_cells=12):
    """An n x n grid of the largest block color, where n = number of block colors:
    colors (other than the background) whose largest connected component has at least min_cells cells."""
    bg = background(grid)
    blocks = {c: max(len(cs) for cs in components(grid, c))
              for c in set(v for row in grid for v in row) - {bg}}
    blocks = {c: s for c, s in blocks.items() if s >= min_cells}
    best = max(blocks, key=blocks.get)
    n = len(blocks)
    return [[best] * n for _ in range(n)]
